package studio.shiren.mobile;
import android.media.*;import android.os.Build;import android.graphics.Rect;import android.content.*;import android.net.Uri;import java.nio.*;import java.io.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Flexible YUV input avoids device-specific Surface/gralloc failures. */
public final class SystemVideoEncoder implements AutoCloseable {
 private MediaCodec codec;private MediaMuxer muxer;private MediaExtractor audio;private MediaFormat audioFormat;private int track=-1,audioTrack=-1;private boolean started=false;private int colorFormat=MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible;private int stride,sliceHeight;private ByteBuffer staging;private final int width,height,fps;private final AtomicBoolean cancel;public String codecName;
 /* 初始化系统硬件编码器。 */ public SystemVideoEncoder(Context app,Uri source,File output,int w,int h,int fps,boolean sound,AtomicBoolean cancel)throws Exception{
  this(app,source,output,w,h,fps,sound,cancel,0);
 }
 /* 按用户目标码率配置系统编码，不默默覆盖导出质量。 */ public SystemVideoEncoder(Context app,Uri source,File output,int w,int h,int fps,boolean sound,AtomicBoolean cancel,int bitrate)throws Exception{
  width=w;height=h;this.fps=fps;this.cancel=cancel;
  try{
   if(sound){audio=new MediaExtractor();audio.setDataSource(app,source,null);for(int i=0;i<audio.getTrackCount();i++){MediaFormat f=audio.getTrackFormat(i);String mime=f.getString(MediaFormat.KEY_MIME);if(mime!=null&&mime.startsWith("audio/")){if(!mime.equals("audio/mp4a-latm"))throw new Exception("这段原声不是 AAC，请关闭保留原声后导出。");audio.selectTrack(i);audio.seekTo(0,MediaExtractor.SEEK_TO_NEXT_SYNC);if(audio.getSampleTime()>=0)audioFormat=f;break;}}}
   MediaFormat format=MediaFormat.createVideoFormat("video/avc",w,h);format.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible);format.setInteger(MediaFormat.KEY_BIT_RATE,bitrate>0?bitrate:Math.max(2000000,(int)(w*(long)h*fps*.15)));format.setInteger(MediaFormat.KEY_FRAME_RATE,fps);format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);format.setInteger(MediaFormat.KEY_COLOR_STANDARD,MediaFormat.COLOR_STANDARD_BT709);format.setInteger(MediaFormat.KEY_COLOR_TRANSFER,MediaFormat.COLOR_TRANSFER_SDR_VIDEO);format.setInteger(MediaFormat.KEY_COLOR_RANGE,MediaFormat.COLOR_RANGE_LIMITED);
   String name=new MediaCodecList(MediaCodecList.REGULAR_CODECS).findEncoderForFormat(format);if(name==null)throw new Exception("当前手机无法编码这个尺寸和帧率，请改为720p/30帧。");if(Build.VERSION.SDK_INT<=29&&name.startsWith("c2.android.")){for(MediaCodecInfo candidate:new MediaCodecList(MediaCodecList.REGULAR_CODECS).getCodecInfos()){if(!candidate.isEncoder()||!candidate.getName().startsWith("OMX.google."))continue;for(String type:candidate.getSupportedTypes())if(type.equals("video/avc")&&candidate.getCapabilitiesForType(type).isFormatSupported(format)){name=candidate.getName();break;}}}codec=MediaCodec.createByCodecName(name);codecName=name;int[] formats=codec.getCodecInfo().getCapabilitiesForType("video/avc").colorFormats;for(int c:formats)if(c==MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Planar){colorFormat=c;break;}if(colorFormat==MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible)for(int c:formats)if(c==MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420SemiPlanar){colorFormat=c;break;}format.setInteger(MediaFormat.KEY_COLOR_FORMAT,colorFormat);format.setInteger(MediaFormat.KEY_STRIDE,w);format.setInteger(MediaFormat.KEY_SLICE_HEIGHT,h);codec.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();MediaFormat accepted=codec.getInputFormat();stride=accepted.containsKey(MediaFormat.KEY_STRIDE)?accepted.getInteger(MediaFormat.KEY_STRIDE):w;sliceHeight=accepted.containsKey(MediaFormat.KEY_SLICE_HEIGHT)?accepted.getInteger(MediaFormat.KEY_SLICE_HEIGHT):h;stride=Math.max(stride,w);sliceHeight=Math.max(sliceHeight,h);android.util.Log.i("ShirenEncoder","format="+accepted+" color="+colorFormat);muxer=new MediaMuxer(output.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);
  }catch(Exception e){close();throw e;}
 }
 /* 取得编码器当前可写入的输入区间。 */ private int input()throws Exception{int waits=0;while(true){VideoSource.check(cancel);int index=codec.dequeueInputBuffer(10000);if(index>=0)return index;drain(false);if(++waits>1500)throw new Exception("视频编码器没有响应，请降低画面大小或帧率。");}}
 /* 写入 YUV 平面并处理步长和像素间隔。 */ private ByteBuffer plane(Image.Plane p,int x,int y){ByteBuffer b=p.getBuffer().duplicate();b.position(b.position()+y*p.getRowStride()+x*p.getPixelStride());return b.slice();}
 /* 取得当前分块所覆盖的源像素范围。 */ private ByteBuffer region(ByteBuffer b,int offset,int length){ByteBuffer d=b.duplicate();d.position(offset);d.limit(offset+length);return d.slice();}
 /* 追加当前视频帧或音轨数据并维护时间戳。 */ public void append(ByteBuffer rgba,int frame)throws Exception{
  int index=input();ByteBuffer input=codec.getInputBuffer(index);if(input==null)throw new Exception("编码输入不可用");int bytes=input.capacity();if(colorFormat!=MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible){int ySize=stride*sliceHeight;int uvStride=colorFormat==MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Planar?(stride+1)/2:stride;int uvSize=uvStride*((sliceHeight+1)/2);int actual=colorFormat==MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Planar?ySize+uvSize*2:ySize+uvSize;if(actual>bytes)throw new Exception("编码缓冲不足");if(staging==null||staging.capacity()<actual)staging=ByteBuffer.allocateDirect(actual);ByteBuffer y=region(staging,0,ySize);ByteBuffer u=region(staging,ySize,uvSize);ByteBuffer v=colorFormat==MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Planar?region(staging,ySize+uvSize,uvSize):region(staging,ySize+1,uvSize-1);int pixel=colorFormat==MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Planar?1:2;if(!NativeCore.rgbaToYuv(rgba,width,height,y,stride,1,u,uvStride,pixel,v,uvStride,pixel))throw new Exception("编码像素写入失败");staging.position(0);staging.limit(actual);input.clear();input.put(staging);codec.queueInputBuffer(index,0,actual,frame*1000000L/fps,0);drain(false);return;}Image image=codec.getInputImage(index);if(image==null)throw new Exception("当前编码器不支持可写的YUV图像输入，请降低输出设置。");Image.Plane[] p=image.getPlanes();Rect crop=image.getCropRect();if(p.length!=3||crop.width()<width||crop.height()<height)throw new Exception("编码器返回了不正确的图像尺寸");
  if(frame==0){String desc="codec="+codecName+" bytes="+bytes+" image="+image.getWidth()+"x"+image.getHeight()+" crop="+crop;for(Image.Plane q:p)desc+=" plane="+q.getBuffer().position()+"/"+q.getBuffer().limit()+"/"+q.getBuffer().capacity()+" stride="+q.getRowStride()+","+q.getPixelStride();android.util.Log.i("ShirenEncoder",desc);}
  boolean ok=NativeCore.rgbaToYuv(rgba,width,height,plane(p[0],crop.left,crop.top),p[0].getRowStride(),p[0].getPixelStride(),plane(p[1],crop.left/2,crop.top/2),p[1].getRowStride(),p[1].getPixelStride(),plane(p[2],crop.left/2,crop.top/2),p[2].getRowStride(),p[2].getPixelStride());if(!ok)throw new Exception("编码图像缓冲不完整");if(frame==0){android.util.Log.i("ShirenEncoder","RGB="+(rgba.get(0)&255)+","+(rgba.get(1)&255)+","+(rgba.get(2)&255)+" YUV="+(p[0].getBuffer().get(0)&255)+","+(p[1].getBuffer().get(0)&255)+","+(p[2].getBuffer().get(0)&255));}codec.queueInputBuffer(index,0,bytes,frame*1000000L/fps,0);drain(false);
 }
 /* 取出已编码数据并交给封装器。 */ private void drain(boolean end)throws Exception{MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int waits=0;while(true){VideoSource.check(cancel);int index=codec.dequeueOutputBuffer(info,end?10000:0);if(index==MediaCodec.INFO_TRY_AGAIN_LATER){if(!end)return;if(++waits>1500)throw new Exception("视频编码超时");}else if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=muxer.addTrack(codec.getOutputFormat());if(audioFormat!=null)audioTrack=muxer.addTrack(audioFormat);muxer.start();started=true;}else if(index>=0){ByteBuffer data=codec.getOutputBuffer(index);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)info.size=0;if(info.size>0){if(!started)throw new Exception("编码轨道尚未就绪");data.position(info.offset);data.limit(info.offset+info.size);ByteBuffer owned=ByteBuffer.allocate(info.size);owned.put(data);owned.flip();MediaCodec.BufferInfo copy=new MediaCodec.BufferInfo();copy.set(0,info.size,info.presentationTimeUs,info.flags);muxer.writeSampleData(track,owned,copy);}boolean eos=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(index,false);if(eos)return;}}}
 /* 完成当前任务并释放编码或缓存资源。 */ public void finish(float seconds)throws Exception{int i=input();codec.queueInputBuffer(i,0,0,(long)(seconds*1000000),MediaCodec.BUFFER_FLAG_END_OF_STREAM);drain(true);if(audioTrack>=0){ByteBuffer bytes=ByteBuffer.allocateDirect(1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long first=audio.getSampleTime();while(audio.getSampleTime()>=0&&audio.getSampleTime()-first<(long)(seconds*1e6)){VideoSource.check(cancel);bytes.clear();int n=audio.readSampleData(bytes,0);if(n<0)break;info.set(0,n,audio.getSampleTime()-first,audio.getSampleFlags());muxer.writeSampleData(audioTrack,bytes,info);audio.advance();}}muxer.stop();started=false;}
 /* 关闭当前对象持有的资源，避免重复占用文件、线程或设备。 */ public void close(){if(codec!=null){try{codec.stop();}catch(Exception ignored){}codec.release();codec=null;}if(muxer!=null){if(started)try{muxer.stop();}catch(Exception ignored){}muxer.release();muxer=null;}if(audio!=null){audio.release();audio=null;}}
}
